'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var getPrototypeOf = require( '@stdlib/utils/get-prototype-of' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var isInt32Array = require( '@stdlib/assert/is-int32array' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var hasOwn = require( '@stdlib/assert/has-own-property' );
var descriptor = require( '@stdlib/utils/property-descriptor' );


// VARIABLES //

var typedArrayPrototype = getPrototypeOf( Float64Array.prototype );
var getLength = descriptor( typedArrayPrototype, 'length' ).get;
var getBuffer = descriptor( typedArrayPrototype, 'buffer' ).get;
var getByteOffset = descriptor( typedArrayPrototype, 'byteOffset' ).get;
var getByteLength = descriptor( typedArrayPrototype, 'byteLength' ).get;


// FUNCTIONS //

/**
* Checks whether a typed view has unmodified metadata and valid indexed elements.
*
* @private
* @param {TypedArray} data - typed view
* @param {integer} count - number of indexed elements
* @param {integer} stride - stride length
* @param {integer} offset - starting index
* @returns {boolean} whether the view is compatible
*/
function isView( data, count, stride, offset ) {
	var length;
	var proto;
	var last;

	proto = getPrototypeOf( data );
	if ( proto !== Float64Array.prototype && proto !== Int32Array.prototype ) {
		return false;
	}
	if ( hasOwn( proto, 'length' ) || hasOwn( proto, 'buffer' ) || hasOwn( proto, 'byteOffset' ) || hasOwn( proto, 'byteLength' ) ) {
		return false;
	}
	if ( hasOwn( data, 'length' ) || hasOwn( data, 'buffer' ) || hasOwn( data, 'byteOffset' ) || hasOwn( data, 'byteLength' ) ) {
		return false;
	}
	if ( !isSafeInteger( stride ) || !isSafeInteger( offset ) ) {
		return false;
	}
	if ( count <= 0 ) {
		return true;
	}
	length = getLength.call( data );
	last = offset + ( (count-1)*stride );
	return isSafeInteger( last ) && offset >= 0 && offset < length && last >= 0 && last < length;
}


// MAIN //

/**
* Checks whether arguments can use the typed native interface.
*
* @private
* @param {Array} args - normalized ndarray arguments
* @returns {boolean} whether arguments can use the native interface
*/
function canUseNative( args ) {
	var pivotOffset;
	var pivotLength;
	var pivotBuffer;
	var dataOffset;
	var dataLength;
	var lengths;
	var pivots;
	var data;
	var N;
	var i;
	var j;

	N = args[ 0 ];
	if ( !isSafeInteger( N ) || N <= 0 || N > 2147483647 ) {
		return false;
	}
	lengths = [ N-1, N, N-1, N-2, N ];
	for ( i = 0; i < 5; i++ ) {
		j = 1 + (3*i);
		data = args[ j ];
		if ( i === 4 ) {
			if ( !isInt32Array( data ) ) {
				return false;
			}
		} else if ( !isFloat64Array( data ) ) {
			return false;
		}
		if ( !isView( data, lengths[ i ], args[ j+1 ], args[ j+2 ] ) ) {
			return false;
		}
	}
	// Deferred pivot copying must not change reads from aliased numeric views.
	pivots = args[ 13 ];
	pivotBuffer = getBuffer.call( pivots );
	pivotOffset = getByteOffset.call( pivots );
	pivotLength = getByteLength.call( pivots );
	for ( i = 0; i < 4; i++ ) {
		data = args[ 1+(3*i) ];
		dataOffset = getByteOffset.call( data );
		dataLength = getByteLength.call( data );
		if ( getBuffer.call( data ) === pivotBuffer && dataOffset < pivotOffset+pivotLength && pivotOffset < dataOffset+dataLength ) {
			return false;
		}
	}
	return true;
}


// EXPORTS //

module.exports = canUseNative;
